// Keep only the items that belong to this pattern (words taken from the examples found in the data).
const PATTERN = /bridge|create|lead|mangere|mixer|quote|replacement|request/i;
return $input.all().filter((item) => {
  const j = item.json;
  const text = [j.subject, j.title, j.text, j.action, j.description].filter(Boolean).join(' ');
  return text === '' || PATTERN.test(text);
});

// If the model call failed or answered badly, pass the item on for a person to handle.
let fields = {};
try { fields = JSON.parse($json.choices[0].message.content); } catch (e) { fields = {}; }
const original = $('Match this pattern').item.json;
const confidence = Number(fields.confidence || 0);
const needs_person = confidence < 0.8;
return { json: { ...original, extracted: fields, confidence, needs_person } };
